# Creates a varied clipboard history for manually testing the full-content
# preview: short/long/unicode text, small/large/odd aspect-ratio images, and
# file drops.
#
# How it works: each sample is put on the real OS clipboard in turn and left
# there long enough for the running app's monitor (150 ms poll) to capture it.
# That means it exercises the real capture path - previews, character/line
# counts, thumbnails, dedup - rather than writing to the database directly.
#
# WARNING: this overwrites the current clipboard contents. No personal data is
# used; every sample is generated by this script.
#
# Usage:
#   powershell -STA -ExecutionPolicy Bypass -File scripts\seed-clipboard.ps1
#
# -STA is required: putting an image on the clipboard (System.Windows.Forms)
# needs a single-threaded apartment.
#
# Notes:
#   - History is capped at 100 items, so seeding may push out older entries.
#   - The app must be running to capture the samples.
#   - The run takes about 30 seconds (fixed pauses so nothing is missed).

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
Add-Type -ReferencedAssemblies System.Drawing @"
using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
public static class ImgGen {
  public static Bitmap Noise(int w, int h, int seed) {
    var bmp = new Bitmap(w, h, PixelFormat.Format32bppArgb);
    var data = bmp.LockBits(new Rectangle(0, 0, w, h), ImageLockMode.WriteOnly, PixelFormat.Format32bppArgb);
    int len = data.Stride * h;
    var bytes = new byte[len];
    var rnd = new Random(seed);
    rnd.NextBytes(bytes);
    for (int i = 3; i < len; i += 4) bytes[i] = 255;
    Marshal.Copy(bytes, 0, data.Scan0, len);
    bmp.UnlockBits(data);
    return bmp;
  }
}
"@

$repoRoot = Split-Path -Parent $PSScriptRoot

"apartment: $([Threading.Thread]::CurrentThread.ApartmentState)"

# Keep every bitmap alive until the end: the clipboard may hold a reference.
$keep = New-Object System.Collections.ArrayList

function Push-Text([string]$t, [int]$wait = 650) {
  for ($i = 0; $i -lt 20; $i++) {
    try { Set-Clipboard -Value $t; break } catch { Start-Sleep -Milliseconds 100 }
  }
  Start-Sleep -Milliseconds $wait
}

function Push-Bitmap([System.Drawing.Bitmap]$bmp, [int]$wait = 950) {
  [void]$keep.Add($bmp)
  $ok = $false
  for ($i = 0; $i -lt 25; $i++) {
    try { [System.Windows.Forms.Clipboard]::SetImage($bmp); $ok = $true; break } catch { Start-Sleep -Milliseconds 150 }
  }
  if (-not $ok) { Write-Host "  image set FAILED ($($bmp.Width)x$($bmp.Height))" }
  Start-Sleep -Milliseconds $wait
}

function New-Canvas([int]$w, [int]$h) {
  return (New-Object System.Drawing.Bitmap($w, $h))
}

# ---------------------------------------------------------------- text samples

Push-Text "Hello, Clippy!"
Push-Text "clipboard"

Push-Text @"
fn main() {
    let items: Vec<&str> = vec!["alpha", "beta"];
    for (i, item) in items.iter().enumerate() {
        println!("{}: {}", i, item);
    }
}
"@

Push-Text "The preview column is meant to show the full content of the selected clipboard entry. It should stay aligned with the main window, appear to the right when there is room, and dock inside when the window is maximized. This paragraph is roughly three hundred characters so the header can display its character and line counts without wrapping too aggressively."

# Long multi-paragraph prose (~14k chars).
$prose = (1..40 | ForEach-Object {
  "Paragraph $_ of the long sample. The preview should scroll smoothly through text of this size without the header or the list column shifting, and without the characters overflowing the panel edge. Each paragraph is deliberately a different length so the scrollbar does not land on a tidy boundary. Extra sentence to pad this one out a little further."
}) -join "`r`n`r`n"
"prose chars: $($prose.Length)"
Push-Text $prose

# One enormous unbroken line (wrapping / horizontal overflow).
$longLine = ("abcdefghij" * 250)
"long line chars: $($longLine.Length)"
Push-Text $longLine

# Unicode, emoji, combining marks, RTL.
$uni = "h" + [char]0x00E9 + "llo w" + [char]0x00F6 + "rld " +
       [char]0x65E5 + [char]0x672C + [char]0x8A9E + " " +
       [char]::ConvertFromUtf32(0x1F389) + [char]::ConvertFromUtf32(0x1F680) +
       " " + [char]0x2014 + " em dash, curly " + [char]0x201C + "quotes" + [char]0x201D +
       ", e" + [char]0x0301 + " combining acute, " +
       [char]0x645 + [char]0x631 + [char]0x62D + [char]0x628 + [char]0x627 +
       " text"
Push-Text $uni

# Tabs, blank lines, ragged indentation.
Push-Text "Name`tType`tSize`r`n`r`nalpha`tint`t12`r`n`r`n`tbeta`tfloat`t3.5`r`n`t`tgamma`tbool`ttrue"

Push-Text @"
{
  "name": "clippy",
  "version": "0.1.0",
  "features": [
    "history",
    "preview",
    "pinning"
  ],
  "window": {
    "width": 712,
    "height": 883,
    "decorations": false,
    "alwaysOnTop": true
  },
  "limits": { "maxHistory": 100, "maxPreviewWidth": 480 }
}
"@

Push-Text @"
# Clipboard Preview

A short document with **bold**, *italic*, and ``inline code``.

- first bullet
- second bullet with a [link](https://example.com/docs?page=2&sort=desc)
- third bullet

```rust
let preview = compute_preview_placement(window)?;
```

> Blockquote: the preview docks inside the main window when there is no room.

1. ordered one
2. ordered two
"@

Push-Text "https://example.com/api/v1/search?query=clipboard+preview+window&filter=type%3Atext&sort=timestamp&order=desc&page=3&pageSize=50&include=payload%2Cmetadata&fields=id%2Ctimestamp%2Ctext%2Cchar_count%2Cline_count&token=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9"

Push-Text @"
SELECT h.id, h.timestamp, h.payload
FROM history AS h
LEFT JOIN pins AS p ON p.item_id = h.id
WHERE h.timestamp >= :since
  AND (h.payload LIKE '%preview%' OR h.payload LIKE '%window%')
GROUP BY h.id
ORDER BY h.timestamp DESC
LIMIT 100;
"@

# Long single-token base64-like value.
$b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
$b64 = -join (1..1200 | ForEach-Object { $b64chars[(Get-Random -Maximum 64)] })
Push-Text $b64

# Windows paths, built from this checkout so no username is baked in.
Push-Text (@(
  (Join-Path $repoRoot "src\preview.ts"),
  (Join-Path $repoRoot "src\main.ts"),
  (Join-Path $repoRoot "src-tauri\src\lib.rs"),
  (Join-Path $repoRoot "src-tauri\capabilities\default.json")
) -join "`r`n")

Push-Text "   leading and trailing spaces   "
Push-Text "    function indented() {`r`n`t`treturn 42;`r`n    }`r`n"

# ~23k character stress sample.
$words = "preview","window","clipboard","select","dock","render","history","toggle","scroll","anchor"
$stress = -join (1..3200 | ForEach-Object { $words[(Get-Random -Maximum 10)] + " " })
"stress chars: $($stress.Length)"
Push-Text $stress

# --------------------------------------------------------------- image samples

# 1x1
$b = New-Canvas 1 1
$b.SetPixel(0, 0, [System.Drawing.Color]::FromArgb(255, 220, 50, 50))
Push-Bitmap $b

# 64x64 icon-ish
$b = New-Canvas 64 64
$g = [System.Drawing.Graphics]::FromImage($b)
$g.Clear([System.Drawing.Color]::FromArgb(255, 32, 34, 40))
$g.FillEllipse((New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(255, 120, 200, 255))), 8, 8, 48, 48)
$g.Dispose()
Push-Bitmap $b

# 480x480 exactly at the thumbnail limit
$b = New-Canvas 480 480
$g = [System.Drawing.Graphics]::FromImage($b)
$g.Clear([System.Drawing.Color]::FromArgb(255, 20, 60, 40))
$g.FillRectangle((New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(255, 90, 220, 140))), 60, 60, 360, 360)
$f = New-Object System.Drawing.Font("Segoe UI", 36)
$g.DrawString("480 x 480", $f, [System.Drawing.Brushes]::White, 100, 210)
$g.Dispose()
Push-Bitmap $b

# 481x481 just over the limit -> thumbnail must be generated
$b = New-Canvas 481 481
$g = [System.Drawing.Graphics]::FromImage($b)
$g.Clear([System.Drawing.Color]::FromArgb(255, 60, 40, 20))
$g.DrawEllipse((New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(255, 240, 200, 120), 24)), 40, 40, 401, 401)
$g.Dispose()
Push-Bitmap $b

# 1200x800 gradient + text
$b = New-Canvas 1200 800
$g = [System.Drawing.Graphics]::FromImage($b)
$rect = New-Object System.Drawing.Rectangle(0, 0, 1200, 800)
$brush = New-Object System.Drawing.Drawing2D.LinearGradientBrush($rect, [System.Drawing.Color]::FromArgb(255, 20, 40, 120), [System.Drawing.Color]::FromArgb(255, 200, 60, 120), 45.0)
$g.FillRectangle($brush, $rect)
$f = New-Object System.Drawing.Font("Segoe UI", 64, [System.Drawing.FontStyle]::Bold)
$g.DrawString("1200 x 800", $f, [System.Drawing.Brushes]::White, 300, 350)
$g.Dispose()
Push-Bitmap $b

# 2000x120 wide banner
$b = New-Canvas 2000 120
$g = [System.Drawing.Graphics]::FromImage($b)
$g.Clear([System.Drawing.Color]::FromArgb(255, 10, 10, 12))
$g.FillRectangle((New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(255, 80, 220, 255))), 0, 40, 2000, 40)
$g.Dispose()
Push-Bitmap $b

# 200x2000 tall strip
$b = New-Canvas 200 2000
$g = [System.Drawing.Graphics]::FromImage($b)
for ($y = 0; $y -lt 2000; $y += 20) {
  $c = [System.Drawing.Color]::FromArgb(255, ($y % 255), 60, (255 - ($y % 255)))
  $g.FillRectangle((New-Object System.Drawing.SolidBrush($c)), 0, $y, 200, 20)
}
$g.Dispose()
Push-Bitmap $b

# Transparent PNG (alpha) 600x400
$b = New-Canvas 600 400
$g = [System.Drawing.Graphics]::FromImage($b)
$g.Clear([System.Drawing.Color]::Transparent)
$g.FillEllipse((New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(160, 255, 180, 40))), 50, 50, 300, 300)
$g.FillEllipse((New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(120, 40, 180, 255))), 250, 100, 300, 300)
$g.Dispose()
Push-Bitmap $b

# 1024x768 noise: expensive to encode, large data URL
$b = [ImgGen]::Noise(1024, 768, 12345)
Push-Bitmap $b 1600

# ----------------------------------------------------------------- file samples

$dir = Join-Path $env:TEMP "opencode\clip-samples"
New-Item -ItemType Directory -Force -Path $dir | Out-Null
Set-Content -Path (Join-Path $dir "notes.txt") -Value "sample notes for the file preview"
Set-Content -Path (Join-Path $dir "data.csv") -Value "a,b,c`r`n1,2,3"
Set-Content -Path (Join-Path $dir "image.png") -Value "not really a png"

$one = New-Object System.Collections.Specialized.StringCollection
$one.Add((Join-Path $dir "notes.txt")) | Out-Null
for ($i = 0; $i -lt 25; $i++) {
  try { [System.Windows.Forms.Clipboard]::SetFileDropList($one); break } catch { Start-Sleep -Milliseconds 150 }
}
Start-Sleep -Milliseconds 800

$many = New-Object System.Collections.Specialized.StringCollection
$many.Add((Join-Path $dir "notes.txt")) | Out-Null
$many.Add((Join-Path $dir "data.csv")) | Out-Null
$many.Add((Join-Path $dir "image.png")) | Out-Null
for ($i = 0; $i -lt 25; $i++) {
  try { [System.Windows.Forms.Clipboard]::SetFileDropList($many); break } catch { Start-Sleep -Milliseconds 150 }
}
Start-Sleep -Milliseconds 900

# Leave the clipboard holding something harmless (and a top-of-list marker).
Set-Clipboard -Value "seeding complete"
Start-Sleep -Milliseconds 700

foreach ($bmp in $keep) { $bmp.Dispose() }
"seeding done"
